import Header from '../components/Header';
import Footer from '../components/Footer';
import React from 'react';
import '../styles/Partitions.css';
import * as a from '../assets';
import { useState } from 'react';

function Partitions() {
    const [showPreview, setShowPreview] = useState(false);

    const pdfUrl = '/documents/game_of_throne.pdf';

    return (
        <div>
            <Header />
            {/* Version iframe
                <div className="pdf-container">
                    <iframe
                        src="/documents/game_of_throne.pdf"
                        width="100%"
                        height="600px"
                        title="Partition Game of Thrones"
                        style={{ border: '2px solid #00ffff', borderRadius: '8px' }}
                    />
                </div>

                {/* Version bouton pour ouvrir le PDF dans un nouvel onglet 
                <div style={{ marginTop: '20px' }}>
                    <a
                        href="/documents/game_of_throne.pdf"
                        target="_blank"
                        rel="noreferrer"
                        className="pdf-button"
                    >
                        Ouvrir le PDF en plein écran
                    </a>
                </div> */}
            <main className="partitions-main">
                <h1>Partitions</h1>

                {/* Logo et titre cliquable */}
                <div
                    className="partition-card"
                    style={{ display: 'flex', alignItems: 'center', cursor: 'pointer', marginBottom: '20px' }}
                    onClick={() => setShowPreview(!showPreview)}
                >
                    <img src={a.logo_partition} alt="PDF Logo" style={{ width: '50px', marginRight: '15px' }} />
                    <span style={{ fontSize: '1.2rem', fontWeight: 'bold', color: '#00ffff' }}>
                        Game of Thrones
                    </span>
                </div>

                {/* Bouton pour ouvrir dans un nouvel onglet */}
                <div style={{ marginBottom: '20px' }}>
                    <a
                        href={pdfUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="pdf-button"
                    >
                        Ouvrir le PDF en plein écran
                    </a>
                </div>

                {/* Aperçu du PDF (iframe) */}
                {showPreview && (
                    <div className="pdf-container">
                        <iframe
                            src={pdfUrl}
                            width="100%"
                            height="600px"
                            title="Preview Game of Thrones"
                            style={{ border: '2px solid #00ffff', borderRadius: '8px' }}
                        />
                    </div>
                )}
            </main>
            <Footer />
        </div>
    );
}



export default Partitions;
